#!/usr/bin/env node
/**
 * Derive every DelayPilot brand asset from one geometry.
 *
 * Owner: visual-asset-director (docs/agents/ROSTER.md §3, `scripts/assets/**`).
 *
 * INPUTS   apps/web/public/brand/mark.svg   — the only hand-authored artwork
 *          scripts/assets/wordmark.json     — Geist outlines, from wordmark-paths.py
 *
 * OUTPUTS  every row of scripts/assets/asset-manifest.mjs except the motifs, which are authored
 *          (radar-arc, route-arcs, grid) or generated by build-globe.mjs (route-globe).
 *
 * WHY A SCRIPT AND NOT A DESIGN TOOL
 * Two hand-drawn versions of a mark is how a brand starts looking cheap. Every icon here is the
 * same path data at a different scale on a different plate, so a nudge to a control point in
 * mark.svg propagates to all thirteen files or to none. Nothing below redraws anything.
 *
 * DETERMINISM
 * A clean re-run reproduces every output byte for byte. There is no timestamp, no random seed, no
 * system font and no ambient state in any output: SVG text is assembled from fixed strings and
 * numbers rounded to 2 decimals, and every raster goes through the one fixed `sharp` option set
 * below with metadata stripped. Verified by running the script twice and diffing sha256 sums; the
 * command is in the handoff report.
 *
 * USAGE
 *   node scripts/assets/build-assets.mjs              # brand, icons, og
 *   node scripts/assets/build-assets.mjs --evidence   # the above, plus design/evidence/s2-mark
 */

import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import sharp from 'sharp'

import { ASSETS } from './asset-manifest.mjs'
import { HEX as COLOR } from './brand-colors.mjs'
import { ACCENT_EXPRESSION, arcPathData, readMark } from './mark-geometry.mjs'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const MARK_PATH = path.join(REPO, 'apps/web/public/brand/mark.svg')
const WORDMARK_PATH = path.join(REPO, 'scripts/assets/wordmark.json')

/* ------------------------------------------------------------------------------------------- */
/* Layout. Every fraction is stated as a fraction of the canvas so the same rule holds at 16 px  */
/* and at 1200 px.                                                                              */
/* ------------------------------------------------------------------------------------------- */

const LAYOUT = {
  favicon: {
    /** The reduction lives on a 24-unit plate with a 5-unit corner radius. */
    plate: 24,
    cornerRadius: 5,
    /** Longest content dimension as a fraction of the plate. 0.73 leaves 3.2 units of padding. */
    contentFraction: 0.73,
  },
  icon: {
    /** Standard ("any") icons: normal padding, rounded plate. */
    contentFraction: 0.62,
    cornerRadiusFraction: 0.22,
  },
  maskable: {
    /*
     * The safe zone is a centred circle of 80% diameter (radius 0.4 x canvas). Scaling the mark so
     * its content bounding CIRCLE is 0.74 x canvas puts the circumradius at 0.37 x canvas: every
     * pixel of meaning sits inside the safe circle with 7.5% of the canvas to spare, on any mask
     * shape a launcher applies. The bounding circle, not the bounding box, is the right measure
     * because the mask is round.
     */
    circumdiameterFraction: 0.74,
  },
  apple: {
    /** iOS applies its own squircle; 0.6 keeps the diagonal composition clear of every corner. */
    contentFraction: 0.6,
  },
  logotype: {
    /** Wordmark cap height as a fraction of the mark's content height. */
    capFraction: 0.6,
    /** Clear gap between the mark's right edge and the wordmark's first ink, in mark-grid units. */
    gap: 6,
  },
  og: {
    width: 1200,
    height: 630,
    /** The 24-unit mark grid is scaled by this to size the mark on the card. */
    markScale: 6.6,
    /** Wordmark and promise-line cap heights in px. */
    wordmarkCap: 68,
    taglineCap: 30,
    /** Gap between the mark's right edge and the wordmark's first ink, in px. */
    gap: 42,
    /** Baseline-to-baseline distance from wordmark to promise line, in px. */
    leading: 110,
    /** Decorative range rings: centre, radii and stroke, in px. Kept clear of all text ink. */
    rings: { cx: 250, cy: 210, radii: [240, 330, 420], strokeWidth: 2 },
  },
  evidence: {
    sizes: [16, 24, 32],
    /** Nearest-neighbour zoom factor for the contact sheets, so pixels are inspectable. */
    zoom: 8,
  },
}

/* ------------------------------------------------------------------------------------------- */
/* Raster encoding. One fixed option set, used everywhere, so output is reproducible.            */
/* ------------------------------------------------------------------------------------------- */

/*
 * `palette` quantises to an indexed PNG, which is what keeps a 512 x 512 icon inside 24 KB.
 * `dither: 0` removes the only stochastic step in that path. No `withMetadata()` call appears
 * anywhere in this file, so libvips writes no EXIF, no ICC profile, no text chunks and no
 * timestamp: metadata is a privacy leak as well as weight.
 */
const PNG_OPTIONS = {
  palette: true,
  colours: 128,
  dither: 0,
  effort: 10,
  compressionLevel: 9,
  adaptiveFiltering: false,
}

/** Lossless WebP: the card is flat colour and type, where lossy leaves rings around the strokes. */
const WEBP_OPTIONS = { lossless: true, effort: 6, smartSubsample: false }

/* ------------------------------------------------------------------------------------------- */
/* Number and path helpers.                                                                     */
/* ------------------------------------------------------------------------------------------- */

/** Round to the charter's 2-decimal ceiling, drop trailing zeros and the leading zero. */
function fmt(value) {
  const rounded = Number(value.toFixed(2))
  const normalised = Object.is(rounded, -0) ? 0 : rounded
  return String(normalised).replace(/^(-?)0\./, '$1.')
}

/** Join numbers for path data, omitting the separator where a leading minus already delimits. */
function pack(values) {
  let out = ''
  for (const value of values) {
    const text = fmt(value)
    if (out !== '' && !text.startsWith('-')) out += ' '
    out += text
  }
  return out
}

/**
 * Apply a uniform scale and a translation to absolute path data.
 *
 * `wordmark.json` is emitted by fontTools' SVGPathPen, which produces absolute M, L, H, V, C, Q
 * and Z only. Anything else throws: silently dropping a command would silently deform a letter.
 */
function transformPath(d, scale, tx, ty) {
  let out = ''
  const segments = d.matchAll(/([MLHVCQZ])([^MLHVCQZ]*)/gi)
  for (const [, commandRaw, argsRaw] of segments) {
    const command = commandRaw.toUpperCase()
    const args = (argsRaw.match(/-?\d*\.?\d+(?:e[-+]?\d+)?/gi) ?? []).map(Number)
    if (command === 'Z') {
      out += 'Z'
      continue
    }
    if (command === 'H') {
      out += `H${pack(args.map((x) => x * scale + tx))}`
      continue
    }
    if (command === 'V') {
      out += `V${pack(args.map((y) => y * scale + ty))}`
      continue
    }
    if (!['M', 'L', 'C', 'Q'].includes(command)) {
      throw new Error(`unsupported path command ${command} in wordmark data`)
    }
    const mapped = args.map((value, index) =>
      index % 2 === 0 ? value * scale + tx : value * scale + ty,
    )
    out += `${command}${pack(mapped)}`
  }
  return out
}

/* ------------------------------------------------------------------------------------------- */
/* Mark composition. Everything below reads `geometry`; nothing redraws.                        */
/* ------------------------------------------------------------------------------------------- */

const geometry = readMark(MARK_PATH)
const wordmarkData = JSON.parse(readFileSync(WORDMARK_PATH, 'utf8'))

/**
 * The three mark elements as an SVG fragment, in the mark's own 24-unit grid.
 *
 * @param {{ink: string, accent: string, includeArc?: boolean}} options
 */
function markElements({ ink, accent, includeArc = true }) {
  const strokes = [includeArc ? geometry.arc : null, geometry.route]
    .filter(Boolean)
    .map((element) => `<path d="${element.d}" stroke-width="${fmt(element.strokeWidth)}"/>`)
    .join('')
  return (
    `<g fill="none" stroke="${ink}" stroke-linecap="round" stroke-linejoin="round">${strokes}</g>` +
    `<circle cx="${fmt(geometry.dot.cx)}" cy="${fmt(geometry.dot.cy)}" r="${fmt(geometry.dot.r)}" fill="${accent}"/>`
  )
}

/**
 * Place the mark on a canvas of `size` px so its measured content box is centred and its longest
 * dimension occupies `contentFraction` of the canvas.
 */
function markPlacement(size, contentFraction, bounds = geometry.content) {
  const scale = (contentFraction * size) / Math.max(bounds.width, bounds.height)
  return { scale, tx: size / 2 - bounds.cx * scale, ty: size / 2 - bounds.cy * scale }
}

/** Place the mark so its content bounding CIRCLE occupies `circumdiameterFraction` of the canvas. */
function maskablePlacement(size, circumdiameterFraction) {
  const scale = (circumdiameterFraction * size) / (geometry.content.circumradius * 2)
  return {
    scale,
    tx: size / 2 - geometry.content.cx * scale,
    ty: size / 2 - geometry.content.cy * scale,
  }
}

/**
 * Wrap a fragment in a placement transform.
 *
 * The two translate arguments are separated by an explicit comma, not by `pack`'s minus-sign
 * delimiter. Path data tolerates `10-5` as two numbers; the SVG transform grammar does not — it
 * requires a `comma-wsp` between them, so `translate(-6.49-.25)` is an invalid transform list, and
 * an invalid transform attribute is dropped whole, which would drop the artwork into the corner.
 * librsvg happens to accept it, so this would have shipped a favicon that rasterises correctly in
 * the build and lands in the wrong place in a browser.
 */
function placed(fragment, { scale, tx, ty }) {
  return `<g transform="translate(${fmt(tx)}, ${fmt(ty)}) scale(${fmt(scale)})">${fragment}</g>`
}

/* ------------------------------------------------------------------------------------------- */
/* SVG outputs.                                                                                 */
/* ------------------------------------------------------------------------------------------- */

const GENERATED_BANNER = (source) =>
  `<!--\n  GENERATED FILE — do not edit. Written by scripts/assets/build-assets.mjs from\n  ${source}. Edit the source and re-run the script; a hand edit here is lost on the\n  next build and breaks the single-geometry guarantee.\n-->\n`

/** mark-mono.svg: the mark with its one accent value collapsed to `currentColor`. */
function buildMarkMono() {
  const source = geometry.source
  if (!source.includes(ACCENT_EXPRESSION)) {
    throw new Error('mark.svg no longer carries the expected accent expression')
  }
  const body = source
    .slice(source.indexOf('<svg'))
    .replace(ACCENT_EXPRESSION, 'currentColor')
    // replaceAll, not replace: the id appears twice — once in `aria-labelledby` and once on the
    // <title> itself. Renaming only the first leaves the reference dangling and the mono mark with
    // no accessible name at all, which is worse than having no name, because it looks handled.
    .replaceAll('dp-mark-title', 'dp-mark-mono-title')
  return (
    GENERATED_BANNER('apps/web/public/brand/mark.svg') +
    '<!--\n' +
    '  Single-colour variant: the advance dot takes `currentColor` with the rest of the mark, for\n' +
    '  print, email, watermarking and the evidence packet, where one ink is the only safe\n' +
    '  assumption. Geometry is byte-identical to mark.svg.\n' +
    '-->\n' +
    body
  )
}

/**
 * favicon.svg: the legible reduction.
 *
 * The radar arc is 2.0 grid units = 1.33 device px at 16 px and muddies there, so it is dropped
 * and the two elements that carry the brand are enlarged into the space it leaves. Same grid,
 * same path data, same file — a reduction, not a second mark. The plate is opaque because a
 * favicon has no page behind it to inherit a background from: a transparent mark in `currentColor`
 * renders black on a black browser chrome.
 */
function buildFaviconSvg() {
  const { plate, cornerRadius, contentFraction } = LAYOUT.favicon
  const placement = markPlacement(plate, contentFraction, geometry.reduced)
  const effectiveStroke = geometry.route.strokeWidth * placement.scale
  return (
    GENERATED_BANNER('apps/web/public/brand/mark.svg') +
    '<!--\n' +
    `  Reduction: radar arc dropped, route line and advance dot scaled by ${fmt(placement.scale)}.\n` +
    `  Effective route stroke ${fmt(effectiveStroke)} units = ${fmt((effectiveStroke / plate) * 16)} device px at 16 px.\n` +
    '  Opaque plate, so the mark does not disappear into a dark browser chrome.\n' +
    '-->\n' +
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${plate} ${plate}" width="${plate}" height="${plate}" role="img" aria-labelledby="dp-favicon-title">` +
    '<title id="dp-favicon-title">DelayPilot</title>' +
    `<rect width="${plate}" height="${plate}" rx="${cornerRadius}" fill="${COLOR.ink}"/>` +
    placed(
      markElements({ ink: COLOR.cloud, accent: COLOR.accentDark, includeArc: false }),
      placement,
    ) +
    '</svg>\n'
  )
}

/**
 * The logotype lockup, in the mark's own 24-unit grid so the mark's path data is unchanged.
 *
 * CLEAR SPACE is locked at 0.5 x the wordmark cap height — an exclusion zone OUTSIDE the viewBox
 * on all four sides. The viewBox is tight to the artwork, so the zone is the consumer's padding to
 * provide, and it scales with the logotype rather than being a fixed pixel value.
 */
function buildLogotype({ mono }) {
  const { capFraction, gap } = LAYOUT.logotype
  const word = wordmarkData.strings.wordmark

  const capHeight = geometry.content.height * capFraction
  const scale = capHeight / word.metrics.capHeight
  // Ink left edge sits `gap` beyond the mark; the glyph outline starts at bounds.xMin, not at 0.
  const tx = geometry.content.xMax + gap - word.bounds.xMin * scale
  // Baseline placed so the wordmark's cap-height centre lands on the mark's content centre. In
  // this y-down space the cap top is `capHeight` above the baseline, so the centre is half that.
  const ty = geometry.content.cy + (word.metrics.capHeight / 2) * scale

  const inkRight = tx + word.bounds.xMax * scale
  // Right inset mirrors the mark's own left inset, so the lockup sits evenly in its box.
  const viewWidth = inkRight + geometry.content.xMin
  const clearSpaceUnits = capHeight / 2
  const clearSpace = fmt(clearSpaceUnits)

  const accent = mono ? 'currentColor' : ACCENT_EXPRESSION
  const titleId = mono ? 'dp-logotype-mono-title' : 'dp-logotype-title'

  return (
    GENERATED_BANNER('apps/web/public/brand/mark.svg and scripts/assets/wordmark.json') +
    '<!--\n' +
    `  Lockup. Mark at its authored 24-unit grid; wordmark cap height ${fmt(capHeight)} units\n` +
    `  (${capFraction} of the mark's content height), first ink ${gap} units clear of the mark.\n` +
    `  CLEAR SPACE: ${clearSpace} units — half the wordmark cap height — as an exclusion zone\n` +
    '  OUTSIDE this viewBox on all four sides. The viewBox is tight to the artwork, so that zone is\n' +
    `  padding the consumer adds: ${clearSpace} px at a rendered height of ${fmt(geometry.viewBox.height)} px,\n` +
    `  scaling with the lockup (it is ${(clearSpaceUnits / geometry.viewBox.height).toFixed(2)} x the rendered height).\n` +
    '  Nothing — rule, divider, container edge, icon or text — may enter it.\n' +
    '  Wordmark glyphs are Geist SemiBold converted to outlines (SIL OFL 1.1, recorded in\n' +
    '  scripts/assets/asset-licenses.json). There is no font reference and no <text> element, so\n' +
    '  this renders identically with no webfont, in librsvg, in email and in print.\n' +
    (mono
      ? '  Monochrome: every element takes `currentColor`, for one-ink reproduction.\n'
      : '  The advance dot keeps the brand accent; see mark.svg for the measured contrast table.\n') +
    '-->\n' +
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${fmt(viewWidth)} ${fmt(geometry.viewBox.height)}" width="${fmt(viewWidth)}" height="${fmt(geometry.viewBox.height)}" role="img" aria-labelledby="${titleId}">` +
    `<title id="${titleId}">DelayPilot</title>` +
    markElements({ ink: 'currentColor', accent }) +
    `<path d="${transformPath(word.path, scale, tx, ty)}" fill="currentColor"/>` +
    '</svg>\n'
  )
}

/* ------------------------------------------------------------------------------------------- */
/* Raster compositions.                                                                         */
/* ------------------------------------------------------------------------------------------- */

function svgDocument(width, height, body) {
  return Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${fmt(width)} ${fmt(height)}" width="${fmt(width)}" height="${fmt(height)}">${body}</svg>`,
  )
}

/** Standard ("any") icon: rounded ink plate, normal padding. */
function iconComposition(size) {
  const radius = size * LAYOUT.icon.cornerRadiusFraction
  return svgDocument(
    size,
    size,
    `<rect width="${fmt(size)}" height="${fmt(size)}" rx="${fmt(radius)}" fill="${COLOR.ink}"/>` +
      placed(
        markElements({ ink: COLOR.cloud, accent: COLOR.accentDark }),
        markPlacement(size, LAYOUT.icon.contentFraction),
      ),
  )
}

/** Maskable icon: ink bleeds to all four edges, meaning inside the 80%-diameter safe circle. */
function maskableComposition(size) {
  return svgDocument(
    size,
    size,
    `<rect width="${fmt(size)}" height="${fmt(size)}" fill="${COLOR.ink}"/>` +
      placed(
        markElements({ ink: COLOR.cloud, accent: COLOR.accentDark }),
        maskablePlacement(size, LAYOUT.maskable.circumdiameterFraction),
      ),
  )
}

/** Apple touch icon: opaque, square, no radius. iOS applies its own mask. */
function appleComposition(size) {
  return svgDocument(
    size,
    size,
    `<rect width="${fmt(size)}" height="${fmt(size)}" fill="${COLOR.ink}"/>` +
      placed(
        markElements({ ink: COLOR.cloud, accent: COLOR.accentDark }),
        markPlacement(size, LAYOUT.apple.contentFraction),
      ),
  )
}

/** The favicon reduction rasterised at an ICO member size. */
function faviconComposition(size) {
  const { plate, cornerRadius, contentFraction } = LAYOUT.favicon
  const scale = size / plate
  return svgDocument(
    size,
    size,
    `<rect width="${fmt(size)}" height="${fmt(size)}" rx="${fmt(cornerRadius * scale)}" fill="${COLOR.ink}"/>` +
      `<g transform="scale(${fmt(scale)})">` +
      placed(
        markElements({ ink: COLOR.cloud, accent: COLOR.accentDark, includeArc: false }),
        markPlacement(plate, contentFraction, geometry.reduced),
      ) +
      '</g>',
  )
}

/**
 * The Open Graph card.
 *
 * A brand-mark composition and nothing else: the mark, the product name and the promise line from
 * DIRECTIVE.md §7. No flight number, gate, terminal, time, date, probability, statistic, review
 * score, screenshot or itinerary detail appears here or may ever be added (AGENTS.md §1.1, §2 —
 * Open Graph tags and images carry no itinerary or personal detail).
 */
function ogComposition() {
  const { width, height, markScale, wordmarkCap, taglineCap, gap, leading, rings } = LAYOUT.og
  const word = wordmarkData.strings.wordmark
  const tag = wordmarkData.strings.tagline

  // Mark, in a local space where the 24-unit grid is scaled by markScale from the origin.
  const markInk = {
    xMin: geometry.content.xMin * markScale,
    xMax: geometry.content.xMax * markScale,
    yMin: geometry.content.yMin * markScale,
    yMax: geometry.content.yMax * markScale,
  }
  const markCentreY = (markInk.yMin + markInk.yMax) / 2

  const wordScale = wordmarkCap / word.metrics.capHeight
  const wordX = markInk.xMax + gap - word.bounds.xMin * wordScale
  const wordBaseline = markCentreY + (word.metrics.capHeight / 2) * wordScale
  const rowInk = {
    xMin: markInk.xMin,
    xMax: wordX + word.bounds.xMax * wordScale,
    yMin: Math.min(markInk.yMin, wordBaseline + word.bounds.yMin * wordScale),
    yMax: Math.max(markInk.yMax, wordBaseline + word.bounds.yMax * wordScale),
  }

  const tagScale = taglineCap / tag.metrics.capHeight
  const tagWidth = (tag.bounds.xMax - tag.bounds.xMin) * tagScale
  const tagX = (rowInk.xMin + rowInk.xMax) / 2 - tagWidth / 2 - tag.bounds.xMin * tagScale
  const tagBaseline = wordBaseline + leading
  const blockInk = {
    xMin: Math.min(rowInk.xMin, tagX + tag.bounds.xMin * tagScale),
    xMax: Math.max(rowInk.xMax, tagX + tag.bounds.xMax * tagScale),
    yMin: rowInk.yMin,
    yMax: tagBaseline + tag.bounds.yMax * tagScale,
  }

  // One translation centres the whole ink block on the card.
  const blockX = width / 2 - (blockInk.xMin + blockInk.xMax) / 2
  const blockY = height / 2 - (blockInk.yMin + blockInk.yMax) / 2

  const ringPaths = rings.radii
    .map(
      (radius) =>
        `<path d="${arcPathData(rings.cx, rings.cy, radius, geometry.arc.start, geometry.arc.end, (value) => Number(fmt(value)))}"/>`,
    )
    .join('')

  return svgDocument(
    width,
    height,
    `<rect width="${width}" height="${height}" fill="${COLOR.ink}"/>` +
      `<g fill="none" stroke="${COLOR.border}" stroke-width="${rings.strokeWidth}" stroke-linecap="round">${ringPaths}</g>` +
      `<g transform="translate(${fmt(blockX)}, ${fmt(blockY)})">` +
      `<g transform="scale(${fmt(markScale)})">${markElements({ ink: COLOR.cloud, accent: COLOR.accentDark })}</g>` +
      `<path d="${transformPath(word.path, wordScale, wordX, wordBaseline)}" fill="${COLOR.cloud}"/>` +
      `<path d="${transformPath(tag.path, tagScale, tagX, tagBaseline)}" fill="${COLOR.muted}"/>` +
      '</g>',
  )
}

/* ------------------------------------------------------------------------------------------- */
/* ICO container. Six-byte header, 16-byte directory entries, then PNG blobs.                   */
/* ------------------------------------------------------------------------------------------- */

/**
 * Write a PNG-in-ICO. Every browser DelayPilot targets reads PNG members at any size, and PNG
 * members are what keep three icons inside 16 KB; a BMP 48 x 48 member alone is 12 KB of pixels.
 *
 * @param {{size: number, png: Buffer}[]} members
 */
function encodeIco(members) {
  const header = Buffer.alloc(6)
  header.writeUInt16LE(0, 0) // reserved
  header.writeUInt16LE(1, 2) // type 1 = icon
  header.writeUInt16LE(members.length, 4)

  const directory = Buffer.alloc(16 * members.length)
  let offset = header.length + directory.length
  members.forEach((member, index) => {
    const at = index * 16
    directory.writeUInt8(member.size >= 256 ? 0 : member.size, at + 0)
    directory.writeUInt8(member.size >= 256 ? 0 : member.size, at + 1)
    directory.writeUInt8(0, at + 2) // palette size: 0 for PNG members
    directory.writeUInt8(0, at + 3) // reserved
    directory.writeUInt16LE(1, at + 4) // colour planes
    directory.writeUInt16LE(32, at + 6) // bits per pixel
    directory.writeUInt32LE(member.png.length, at + 8)
    directory.writeUInt32LE(offset, at + 12)
    offset += member.png.length
  })

  return Buffer.concat([header, directory, ...members.map((member) => member.png)])
}

/* ------------------------------------------------------------------------------------------- */
/* Emitters.                                                                                    */
/* ------------------------------------------------------------------------------------------- */

const written = []

function writeOut(relativePath, contents) {
  const absolute = path.join(REPO, relativePath)
  mkdirSync(path.dirname(absolute), { recursive: true })
  writeFileSync(absolute, contents)
  written.push({ path: relativePath, bytes: statSync(absolute).size })
}

async function png(svg, { opaque = false } = {}) {
  let pipeline = sharp(svg)
  // `flatten` + `removeAlpha` is what makes the Apple icon genuinely alpha-free rather than
  // merely fully opaque: iOS renders an alpha channel it finds as black.
  if (opaque) pipeline = pipeline.flatten({ background: COLOR.ink }).removeAlpha()
  return pipeline.png(PNG_OPTIONS).toBuffer()
}

async function build() {
  writeOut('apps/web/public/brand/mark-mono.svg', buildMarkMono())
  writeOut('apps/web/public/brand/logotype.svg', buildLogotype({ mono: false }))
  writeOut('apps/web/public/brand/logotype-mono.svg', buildLogotype({ mono: true }))
  writeOut('apps/web/public/icons/favicon.svg', buildFaviconSvg())

  writeOut('apps/web/public/icons/icon-192.png', await png(iconComposition(192)))
  writeOut('apps/web/public/icons/icon-512.png', await png(iconComposition(512)))
  writeOut(
    'apps/web/public/icons/icon-192-maskable.png',
    await png(maskableComposition(192), { opaque: true }),
  )
  writeOut(
    'apps/web/public/icons/icon-512-maskable.png',
    await png(maskableComposition(512), { opaque: true }),
  )
  writeOut(
    'apps/web/public/icons/apple-touch-icon-180.png',
    await png(appleComposition(180), { opaque: true }),
  )

  const icoMembers = []
  for (const size of [16, 32, 48]) {
    icoMembers.push({ size, png: await png(faviconComposition(size), { opaque: true }) })
  }
  writeOut('apps/web/public/icons/favicon.ico', encodeIco(icoMembers))

  const og = ogComposition()
  writeOut('apps/web/public/og/default-1200x630.png', await sharp(og).png(PNG_OPTIONS).toBuffer())
  writeOut(
    'apps/web/public/og/default-1200x630.webp',
    await sharp(og).webp(WEBP_OPTIONS).toBuffer(),
  )
}

/** The mark drawn at `size` px on a theme surface — the subject of the legibility evidence. */
function evidenceMark(size, theme) {
  return svgDocument(
    size,
    size,
    `<rect width="${size}" height="${size}" fill="${theme.background}"/>` +
      placed(
        markElements({ ink: theme.ink, accent: theme.accent }),
        markPlacement(size, LAYOUT.icon.contentFraction),
      ),
  )
}

/** Nearest-neighbour contact sheet: no resampling is allowed to soften the evidence. */
async function contactSheet(render) {
  const { sizes, zoom } = LAYOUT.evidence
  const tiles = []
  let left = zoom
  for (const size of sizes) {
    const input = await sharp(render(size))
      .resize(size * zoom, size * zoom, { kernel: 'nearest' })
      .png(PNG_OPTIONS)
      .toBuffer()
    // Tiles share a baseline so the three sizes are directly comparable.
    tiles.push({ input, left, top: zoom + (Math.max(...sizes) - size) * zoom })
    left += size * zoom + zoom * 2
  }
  return sharp({
    create: {
      width: left - zoom,
      height: Math.max(...sizes) * zoom + zoom * 2,
      channels: 3,
      // Neutral 18% grey: a mid surface that favours neither theme's tiles.
      background: '#767676',
    },
  })
    .composite(tiles)
    .png(PNG_OPTIONS)
    .toBuffer()
}

/**
 * Legibility evidence for `accessibility-lead`: the mark at 16, 24 and 32 px on the light and dark
 * surfaces, in colour and in greyscale, plus the favicon reduction at the same sizes, plus
 * nearest-neighbour contact sheets so the actual pixel grid is inspectable rather than described.
 *
 * The favicon set is emitted once, not once per theme: the reduction carries its own opaque ink
 * plate, so it is byte-identical on a light and a dark page. Emitting `favicon-16-dark.png` and
 * `favicon-16-light.png` as identical files would imply a theme response the artwork does not
 * have, and evidence that overstates is worse than no evidence.
 */
async function buildEvidence() {
  const { sizes } = LAYOUT.evidence
  const themes = [
    { name: 'light', background: COLOR.cloud, ink: COLOR.ink, accent: COLOR.accentLight },
    { name: 'dark', background: COLOR.inkDeep, ink: COLOR.cloud, accent: COLOR.accentDark },
  ]

  for (const theme of themes) {
    for (const size of sizes) {
      const svg = evidenceMark(size, theme)
      const base = `design/evidence/s2-mark/mark-${size}-${theme.name}`
      writeOut(`${base}.png`, await sharp(svg).png(PNG_OPTIONS).toBuffer())
      writeOut(`${base}-grey.png`, await sharp(svg).greyscale().png(PNG_OPTIONS).toBuffer())
    }
    writeOut(
      `design/evidence/s2-mark/mark-contact-${theme.name}.png`,
      await contactSheet((size) => evidenceMark(size, theme)),
    )
  }

  for (const size of sizes) {
    const svg = faviconComposition(size)
    const base = `design/evidence/s2-mark/favicon-${size}`
    writeOut(`${base}.png`, await sharp(svg).png(PNG_OPTIONS).toBuffer())
    writeOut(`${base}-grey.png`, await sharp(svg).greyscale().png(PNG_OPTIONS).toBuffer())
  }
  writeOut(
    'design/evidence/s2-mark/favicon-contact.png',
    await contactSheet((size) => faviconComposition(size)),
  )
}

/* ------------------------------------------------------------------------------------------- */

async function main() {
  const wantsEvidence = process.argv.includes('--evidence')
  await build()
  if (wantsEvidence) await buildEvidence()

  const budgets = new Map(ASSETS.map((asset) => [asset.path, asset.bytes]))
  let over = 0
  console.log('asset                                             bytes    budget  ')
  for (const file of written) {
    const budget = budgets.get(file.path)
    const marker = budget === undefined ? '' : file.bytes > budget ? '  OVER BUDGET' : '  ok'
    if (budget !== undefined && file.bytes > budget) over += 1
    console.log(
      `${file.path.padEnd(48)} ${String(file.bytes).padStart(7)} ${
        budget === undefined ? '      —' : String(budget).padStart(7)
      }${marker}`,
    )
  }
  console.log(`\n${written.length} files written.`)
  if (over > 0) {
    console.error(`${over} file(s) over budget. Run scripts/assets/verify-assets.mjs for detail.`)
    return 1
  }
  return 0
}

process.exitCode = await main()
